-- JimuReport 2.5.1 DDL (compact)
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS `chat2bi_assistant` ( `id` varchar(32) NOT NULL, `name` varchar(100) NOT NULL, `avatar` varchar(20) NULL DEFAULT NULL, `description` varchar(500) NULL DEFAULT NULL, `welcome` varchar(500) NULL DEFAULT NULL, `domain_id` varchar(32) NULL DEFAULT NULL, `domain_ids` varchar(1000) NULL DEFAULT NULL, `show_sql` varchar(1) NULL DEFAULT NULL, `status` varchar(20) NULL DEFAULT NULL, `questions_json` text NULL, `sort_no` int(11) NULL DEFAULT NULL, `perm_json` text NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_assistant_domain`(`domain_id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_conversation` ( `id` varchar(32) NOT NULL, `assistant_id` varchar(32) NOT NULL, `domain_id` varchar(32) NULL DEFAULT NULL, `title` varchar(100) NULL DEFAULT NULL, `create_by` varchar(50) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_conv_ast_user`(`assistant_id`, `create_by`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_domain` ( `id` varchar(32) NOT NULL, `name` varchar(100) NOT NULL, `description` varchar(500) NULL DEFAULT NULL, `datasource_id` varchar(36) NULL DEFAULT NULL, `status` varchar(20) NULL DEFAULT NULL, `sort_no` int(11) NULL DEFAULT NULL, `joins_json` text NULL, `perm_json` text NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_message` ( `id` varchar(32) NOT NULL, `conversation_id` varchar(32) NOT NULL, `role` varchar(10) NULL DEFAULT NULL, `content` text NULL, `msg_json` mediumtext NULL, `sort_no` int(11) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_msg_conv`(`conversation_id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_table` ( `id` varchar(32) NOT NULL, `domain_id` varchar(32) NOT NULL, `name` varchar(100) NOT NULL, `label` varchar(100) NULL DEFAULT NULL, `mode` varchar(20) NULL DEFAULT NULL, `sql_text` text NULL, `columns_json` text NULL, `sort_no` int(11) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_table_domain`(`domain_id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_table_meta` ( `id` varchar(32) NOT NULL, `db_source_type` varchar(32) NOT NULL, `db_source_id` varchar(32) NOT NULL, `schema_name` varchar(128) NULL DEFAULT NULL, `table_name` varchar(128) NOT NULL, `source_comment` varchar(512) NULL DEFAULT NULL, `table_comment` varchar(512) NULL DEFAULT NULL, `columns_json` text NOT NULL, `relations_json` text NULL, `is_enabled` tinyint(4) NOT NULL DEFAULT 1, `synced_time` datetime NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, UNIQUE INDEX `uk_source_table`(`db_source_type`, `db_source_id`, `schema_name`, `table_name`) USING BTREE, INDEX `idx_source`(`db_source_type`, `db_source_id`) USING BTREE, INDEX `idx_table_name`(`table_name`) USING BTREE, INDEX `idx_table_name_comment`(`table_name`, `source_comment`(320), `table_comment`(320)) USING BTREE, INDEX `idx_table_comment`(`table_comment`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_term` ( `id` varchar(32) NOT NULL, `domain_id` varchar(32) NOT NULL, `name` varchar(100) NOT NULL, `synonyms_json` text NULL, `description` varchar(500) NULL DEFAULT NULL, `apply_kind` varchar(20) NULL DEFAULT NULL, `apply_time` varchar(50) NULL DEFAULT NULL, `apply_clause` varchar(500) NULL DEFAULT NULL, `sort_no` int(11) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_term_domain`(`domain_id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `chat2bi_topic` ( `id` varchar(32) NOT NULL, `domain_id` varchar(32) NOT NULL, `name` varchar(100) NOT NULL, `description` varchar(500) NULL DEFAULT NULL, `status` varchar(20) NULL DEFAULT NULL, `fields_json` text NULL, `sort_no` int(11) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `tenant_id` int(11) NULL DEFAULT 0, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_c2b_topic_domain`(`domain_id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `demo` ( `id` varchar(50) NOT NULL, `name` varchar(30) NULL DEFAULT NULL, `key_word` varchar(255) NULL DEFAULT NULL, `punch_time` datetime NULL DEFAULT NULL, `salary_money` decimal(10, 3) NULL DEFAULT NULL, `bonus_money` double(10, 2) NULL DEFAULT NULL, `sex` varchar(2) NULL DEFAULT NULL, `age` int(11) NULL DEFAULT NULL, `birthday` date NULL DEFAULT NULL, `email` varchar(50) NULL DEFAULT NULL, `content` varchar(1000) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `sys_org_code` varchar(64) NULL DEFAULT NULL, `tenant_id` int(10) NULL DEFAULT 0, `update_count` int(11) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `huiyuan_age` ( `id` varchar(36) NOT NULL, `name` varchar(50) NULL DEFAULT NULL, `value` varchar(20) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

