CREATE TABLE IF NOT EXISTS `huiyuan_sex` ( `id` varchar(36) NOT NULL, `name` varchar(50) NULL DEFAULT NULL, `value` varchar(20) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

