CREATE TABLE IF NOT EXISTS `huiyuan_wxtl` ( `id` varchar(36) NOT NULL, `name` varchar(50) NULL DEFAULT NULL, `value` varchar(20) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `huiyuan_wxtlshuliang` ( `id` varchar(36) NOT NULL, `name` varchar(50) NULL DEFAULT NULL, `value` int(10) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `huiyuan_xueli` ( `id` varchar(36) NOT NULL, `name` varchar(50) NULL DEFAULT NULL, `value` varchar(20) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `ins_claim` ( `id` bigint(20) NOT NULL, `claim_no` varchar(32) NULL DEFAULT NULL, `policy_id` bigint(20) NULL DEFAULT NULL, `policy_no` varchar(32) NULL DEFAULT NULL, `cust_name` varchar(50) NULL DEFAULT NULL, `product_type` varchar(20) NULL DEFAULT NULL, `report_date` date NULL DEFAULT NULL, `claim_type` varchar(20) NULL DEFAULT NULL, `claim_amount` decimal(12, 2) NULL DEFAULT NULL, `settle_amount` decimal(12, 2) NULL DEFAULT NULL, `status` varchar(12) NULL DEFAULT NULL, `province` varchar(20) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `ins_customer` ( `id` bigint(20) NOT NULL, `cust_no` varchar(32) NULL DEFAULT NULL, `cust_name` varchar(50) NULL DEFAULT NULL, `gender` varchar(4) NULL DEFAULT NULL, `age` int(11) NULL DEFAULT NULL, `province` varchar(20) NULL DEFAULT NULL, `city` varchar(20) NULL DEFAULT NULL, `region` varchar(10) NULL DEFAULT NULL, `occupation` varchar(20) NULL DEFAULT NULL, `cust_level` varchar(10) NULL DEFAULT NULL, `reg_date` date NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `ins_policy` ( `id` bigint(20) NOT NULL, `policy_no` varchar(32) NULL DEFAULT NULL, `cust_id` bigint(20) NULL DEFAULT NULL, `cust_name` varchar(50) NULL DEFAULT NULL, `product_name` varchar(50) NULL DEFAULT NULL, `product_type` varchar(20) NULL DEFAULT NULL, `channel` varchar(20) NULL DEFAULT NULL, `premium` decimal(12, 2) NULL DEFAULT NULL, `coverage_amount` decimal(14, 2) NULL DEFAULT NULL, `term_years` int(11) NULL DEFAULT NULL, `sign_date` date NULL DEFAULT NULL, `effect_date` date NULL DEFAULT NULL, `expire_date` date NULL DEFAULT NULL, `status` varchar(12) NULL DEFAULT NULL, `province` varchar(20) NULL DEFAULT NULL, `region` varchar(10) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `jimu_dict` ( `id` varchar(32) NOT NULL, `dict_name` varchar(100) NULL DEFAULT NULL, `dict_code` varchar(100) NULL DEFAULT NULL, `description` varchar(255) NULL DEFAULT NULL, `del_flag` int(1) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `type` int(1) UNSIGNED ZEROFILL NULL DEFAULT 0, `tenant_id` varchar(10) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, UNIQUE INDEX `uk_sd_dict_code`(`dict_code`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `jimu_dict_item` ( `id` varchar(32) NOT NULL, `dict_id` varchar(32) NULL DEFAULT NULL, `item_text` varchar(100) NULL DEFAULT NULL, `item_value` varchar(100) NULL DEFAULT NULL, `description` varchar(255) NULL DEFAULT NULL, `sort_order` int(10) NULL DEFAULT NULL, `status` int(11) NULL DEFAULT NULL, `create_by` varchar(32) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(32) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_sdi_role_dict_id`(`dict_id`) USING BTREE, INDEX `idx_sdi_role_sort_order`(`sort_order`) USING BTREE, INDEX `idx_sdi_status`(`status`) USING BTREE, INDEX `idx_sdi_dict_val`(`dict_id`, `item_value`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `jimu_report` ( `id` varchar(32) NOT NULL, `code` varchar(50) NULL DEFAULT NULL, `name` varchar(50) NULL DEFAULT NULL, `note` varchar(255) NULL DEFAULT NULL, `status` varchar(10) NULL DEFAULT NULL, `type` varchar(50) NULL DEFAULT NULL, `json_str` longtext NULL, `api_url` varchar(255) NULL DEFAULT NULL, `thumb` text NULL, `create_by` varchar(50) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(50) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `del_flag` tinyint(1) NULL DEFAULT NULL, `api_method` varchar(255) NULL DEFAULT NULL, `api_code` varchar(255) NULL DEFAULT NULL, `template` tinyint(1) NULL DEFAULT NULL, `view_count` bigint(15) NULL DEFAULT 0, `css_str` text NULL, `js_str` text NULL, `py_str` text NULL, `tenant_id` varchar(10) NULL DEFAULT NULL, `update_count` int(11) NULL DEFAULT 0, `submit_form` tinyint(1) NULL DEFAULT NULL, `is_multi_sheet` tinyint(4) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, UNIQUE INDEX `uniq_jmreport_code`(`code`) USING BTREE, INDEX `uniq_jmreport_createby`(`create_by`) USING BTREE, INDEX `uniq_jmreport_delflag`(`del_flag`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

