CREATE TABLE IF NOT EXISTS `jimu_report_db` ( `id` varchar(36) NOT NULL, `jimu_report_id` varchar(32) NULL DEFAULT NULL, `create_by` varchar(50) NULL DEFAULT NULL, `update_by` varchar(50) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `db_code` varchar(32) NULL DEFAULT NULL, `db_ch_name` varchar(50) NULL DEFAULT NULL, `db_type` varchar(32) NULL DEFAULT NULL, `db_table_name` varchar(32) NULL DEFAULT NULL, `db_dyn_sql` longtext NULL, `db_key` varchar(32) NULL DEFAULT NULL, `tb_db_key` varchar(32) NULL DEFAULT NULL, `tb_db_table_name` varchar(32) NULL DEFAULT NULL, `java_type` varchar(32) NULL DEFAULT NULL, `java_value` varchar(255) NULL DEFAULT NULL, `api_url` varchar(255) NULL DEFAULT NULL, `api_method` varchar(255) NULL DEFAULT NULL, `is_list` varchar(10) NULL DEFAULT '0', `is_page` varchar(10) NULL DEFAULT NULL, `db_source` varchar(255) NULL DEFAULT NULL, `db_source_type` varchar(50) NULL DEFAULT NULL, `json_data` text NULL, `api_convert` varchar(255) NULL DEFAULT NULL, `iz_shared_source` int(1) NULL DEFAULT NULL, `jimu_shared_source_id` varchar(32) NULL DEFAULT NULL, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_jmreportdb_db_key`(`db_key`) USING BTREE, INDEX `idx_jimu_report_id`(`jimu_report_id`) USING BTREE, INDEX `idx_db_source_id`(`db_source`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

CREATE TABLE IF NOT EXISTS `jimu_report_db_field` ( `id` varchar(36) NOT NULL, `create_by` varchar(50) NULL DEFAULT NULL, `create_time` datetime NULL DEFAULT NULL, `update_by` varchar(50) NULL DEFAULT NULL, `update_time` datetime NULL DEFAULT NULL, `jimu_report_db_id` varchar(32) NULL DEFAULT NULL, `field_name` varchar(80) NULL DEFAULT NULL, `field_name_physics` varchar(200) NULL DEFAULT NULL, `field_text` varchar(50) NULL DEFAULT NULL, `widget_type` varchar(50) NULL DEFAULT NULL, `widget_width` int(10) NULL DEFAULT NULL, `order_num` int(3) NULL DEFAULT NULL, `search_flag` int(3) NULL DEFAULT 0, `search_mode` int(3) NULL DEFAULT NULL, `dict_code` varchar(255) NULL DEFAULT NULL, `search_value` varchar(100) NULL DEFAULT NULL, `search_format` varchar(50) NULL DEFAULT NULL, `ext_json` text NULL, PRIMARY KEY (`id`) USING BTREE, INDEX `idx_jrdf_jimu_report_db_id`(`jimu_report_db_id`) USING BTREE, INDEX `idx_dbfield_order_num`(`order_num`) USING BTREE ) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

